-- Account-level invariants apply even when several Workers change access concurrently.
CREATE TRIGGER protect_last_admin_update BEFORE UPDATE OF role ON user_churches WHEN OLD.role='admin' AND NEW.role<>'admin' AND NOT EXISTS(SELECT 1 FROM user_churches uc JOIN users u ON u.id=uc.userId WHERE uc.churchId=OLD.churchId AND uc.role='admin' AND uc.userId<>OLD.userId AND u.disabled=0 AND u.passwordState='active') BEGIN SELECT RAISE(ABORT,'CHECK constraint failed: last_bootstrap_administrator'); END;
CREATE TRIGGER protect_last_admin_delete BEFORE DELETE ON user_churches WHEN OLD.role='admin' AND NOT EXISTS(SELECT 1 FROM user_churches uc JOIN users u ON u.id=uc.userId WHERE uc.churchId=OLD.churchId AND uc.role='admin' AND uc.userId<>OLD.userId AND u.disabled=0 AND u.passwordState='active') BEGIN SELECT RAISE(ABORT,'CHECK constraint failed: last_bootstrap_administrator'); END;
CREATE TRIGGER protect_last_admin_disable BEFORE UPDATE OF disabled ON users WHEN NEW.disabled=1 AND OLD.disabled=0 AND EXISTS(SELECT 1 FROM user_churches uc WHERE uc.userId=OLD.id AND uc.role='admin' AND NOT EXISTS(SELECT 1 FROM user_churches other JOIN users u ON u.id=other.userId WHERE other.churchId=uc.churchId AND other.role='admin' AND other.userId<>OLD.id AND u.disabled=0 AND u.passwordState='active')) BEGIN SELECT RAISE(ABORT,'CHECK constraint failed: last_bootstrap_administrator'); END;
CREATE TRIGGER revoke_admin_invitations_update AFTER UPDATE OF role ON user_churches WHEN OLD.role='admin' AND NEW.role<>'admin' BEGIN UPDATE auth_invitations SET revokedAt=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE churchId=OLD.churchId AND createdBy=OLD.userId AND consumedAt IS NULL AND revokedAt IS NULL; END;
CREATE TRIGGER revoke_admin_invitations_delete AFTER DELETE ON user_churches WHEN OLD.role='admin' BEGIN UPDATE auth_invitations SET revokedAt=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE churchId=OLD.churchId AND createdBy=OLD.userId AND consumedAt IS NULL AND revokedAt IS NULL; END;
CREATE TRIGGER revoke_disabled_account AFTER UPDATE OF disabled ON users WHEN NEW.disabled=1 BEGIN DELETE FROM sessions WHERE userId=NEW.id; UPDATE auth_invitations SET revokedAt=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE (userId=NEW.id OR createdBy=NEW.id) AND consumedAt IS NULL AND revokedAt IS NULL; END;
CREATE TRIGGER revoke_password_version AFTER UPDATE OF passwordVersion ON users WHEN NEW.passwordVersion<>OLD.passwordVersion BEGIN DELETE FROM sessions WHERE userId=NEW.id AND passwordVersion<>NEW.passwordVersion; UPDATE auth_invitations SET revokedAt=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE (userId=NEW.id OR createdBy=NEW.id) AND consumedAt IS NULL AND revokedAt IS NULL; END;
CREATE TRIGGER revoke_changed_person_invitations AFTER UPDATE OF email,removed ON people WHEN lower(NEW.email)<>lower(OLD.email) OR NEW.removed<>OLD.removed BEGIN UPDATE auth_invitations SET revokedAt=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE churchId=NEW.churchId AND personId=NEW.id AND consumedAt IS NULL AND revokedAt IS NULL; END;
